#include <stdio.h>
#include <queue>
using namespace std;

int main() {
    int n, m;
    scanf("%d%d", &n, &m);

    char a[110];
    scanf("%s", a);

    int s = -1, e = -1;
    bool visited[110] = {};

    for (int i = 0; i < n; ++i) {
        if (a[i] == 'G') s = i;
        else if (a[i] == 'T') e = i;
    }

    queue<int> q;
    q.push(s);
    visited[s] = true;

    while (!q.empty()) {
        int now = q.front();
        q.pop();

        if (now == e) {
            printf("YES");
            return 0;
        }

        if (now + m < n && !visited[now + m] && a[now + m] != '#') {
            visited[now + m] = true;
            q.push(now + m);
        }

        if (now - m >= 0 && !visited[now - m] && a[now - m] != '#') {
            visited[now - m] = true;
            q.push(now - m);
        }
    }

    printf("NO");
    return 0;
}

